    gsl_function = GSLFunction()
    gsl_function.func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(lambda x: func(x))

    workspace = (ctypes.c_double * workspace_size)()
    result = ctypes.c_double()
    error = ctypes.c_double()
    neval = ctypes.c_size_t()

    status = gsl.gsl_integration_cquad(ctypes.pointer(gsl_function), a, b, epsabs, epsrel, workspace_size, ctypes.pointer(workspace), ctypes.pointer(result), ctypes.pointer(error), ctypes.pointer(neval))

