def compute_weighted_mean(weights, data):
    """Compute the weighted mean using GSL's gsl_stats_wmean function."""

    # Check if inputs are valid lists of floats
    if not isinstance(weights, list) or not isinstance(data, list):
        raise TypeError("Inputs must be lists.")

    if not all(isinstance(x, (int, float)) for x in weights) or not all(isinstance(x, (int, float)) for x in data):
        raise TypeError("All elements must be numeric.")

    if len(weights) != len(data):
        raise ValueError("Weights and data arrays must have the same length.")

    if len(weights) == 0:
        raise ValueError("Input arrays cannot be empty.")

    # Load GSL libraries in the required order
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError:
        raise RuntimeError("GSL libraries not found. Check the installation and path.")

    # Define function signature for gsl_stats_wmean
    gsl.gsl_stats_wmean.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t]
    gsl.gsl_stats_wmean.restype = ctypes.c_double

    # Convert Python lists to C arrays
    weights_array = (ctypes.c_double * len(weights))(*weights)
    data_array = (ctypes.c_double * len(data))(*data)

    # Compute weighted mean
    result = gsl.gsl_stats_wmean(data_array, weights_array, ctypes.c_size_t(len(data)), ctypes.c_size_t(len(weights)))

    return float(result)

