class GSLVector:
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_double * size)()
        self.handle = gsl.gsl_vector_alloc(size)

    def set_data(self, values):
        for i in range(self.size):
            ctypes.c_double.from_address(ctypes.addressof(self.data[i])) = ctypes.c_double(values[i])
        gsl.gsl_vector_set(self.handle, 0, ctypes.c_double(values[0]))

    def get_data(self):
        result = [0.0] * self.size
