    _fields_ = [('size1', ctypes.c_size_t), ('size2', ctypes.c_size_t), ('data', ctypes.POINTER(ctypes.c_double))]

    @classmethod
    def from_list_of_lists(cls, lst):
        size1 = len(lst)
        size2 = len(lst[0]) if size1 > 0 else 0
        data = (ctypes.c_double * (size1 * size2))(*[val for row in lst for val in row])
        return cls(size1, size2, data)


