import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = np.array(matrix, dtype=np.float64)
        self.size = len(matrix)
        self.data = self.matrix.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    def __del__(self):
        pass

    def to_gsl(self):
        return ctypes.POINTER(ctypes.c_double)(self.data)

    @classmethod
def create_gsl_matrix(matrix):
    return GSLMatrix(matrix)

    @classmethod
def extract_matrix(gsl_matrix):
    return GSLMatrix(np.ctypeslib.as_array(gsl_matrix, shape=(gsl_matrix.contents.size, gsl_matrix.contents.size)))

def apply_givens_qr(M, N, Q, R, i, j, c, s):
    libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl.gsl_matrix_set.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t, ctypes.c_double]
    gsl.gsl_matrix_get.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t]
    gsl.apply_givens_qr.argtypes = [ctypes.c_size_t, ctypes.c_size_t, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t, ctypes.c_double, ctypes.c_double]

    gsl.apply_givens_qr(M, N, Q.to_gsl(), R.to_gsl(), i, j, c, s)

    Q_matrix = extract_matrix(Q.to_gsl())
    R_matrix = extract_matrix(R.to_gsl())

    assert np.allclose(Q_matrix.matrix, Q.matrix), "Q matrix not updated correctly"
    assert np.allclose(R_matrix.matrix, R.matrix), "R matrix not updated correctly"

    return Q_matrix.matrix, R_matrix.matrix

