    gsl.gsl_sf_bessel_sequence_Jnu_e.argtypes = [ctypes.c_double, ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_sf_bessel_sequence_Jnu_e.restype = ctypes.c_int

    size = len(v)
    if size == 0:
        return []

    v_array = (ctypes.c_double * size)(*v)
    result = (ctypes.c_double * size)()

    error_code = gsl.gsl_sf_bessel_sequence_Jnu_e(ctypes.c_double(nu), ctypes.c_int(mode), v_array, result)

    if error_code != 0:
        raise GSL_Error(f"GSL error code {error_code}")

    return list(result)

