        gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int

        n = self.size[0]
        status = gsl.gsl_linalg_cholesky_decomp(ctypes.pointer(ctypes.c_int(n)), self.pointer)
        return status == 0

    def cholesky_decomp(self):
